export const createList = defineFunction({
  name: "hubspot.create_list",
  connector: "hubspot",
  class: "write",
  act: true,
  description: "Create a list (a segment) of records of one object type. MANUAL: members added and removed by hand or by add_and_remove_list_memberships. DYNAMIC: members recomputed by HubSpot from filter_branch. SNAPSHOT: filtered once, then managed by hand. The name is unique per object type.",
  schema: {
    "type": "object",
    "additionalProperties": false,
    "required": ["name", "object_type_id", "processing_type"],
    "properties": {
      "name": {"type": "string", "minLength": 1, "description": "List name, unique per object type."},
      "object_type_id": {
        "type": "string",
        "pattern": "^[0-9]+-[0-9]+$",
        "description": "0-1 contacts, 0-2 companies, 0-3 deals, 0-5 tickets, 2-<n> a custom object."
      },
      "processing_type": {"enum": ["MANUAL", "DYNAMIC", "SNAPSHOT"]},
      "filter_branch": {
        "type": "object",
        "required": ["filterBranchType"],
        "description": "HubSpot's criteria tree (filterBranchType OR, AND, UNIFIED_EVENTS, ASSOCIATION, with filterBranches and filters), passed as is; properties by internal name."
      },
      "custom_properties": {
        "type": "object",
        "minProperties": 1,
        "additionalProperties": {"type": "string"},
        "description": "Custom list properties, name to value."
      }
    }
  },
  examples: [
    { title: "A manual list of contacts", input: {"name": "Conference leads", "object_type_id": "0-1", "processing_type": "MANUAL"} },
    { title: "A dynamic list of contacts by lifecycle stage", input: {"name": "Customers", "object_type_id": "0-1", "processing_type": "DYNAMIC", "filter_branch": {"filterBranchType": "OR", "filterBranches": [{"filterBranchType": "AND", "filters": [{"filterType": "PROPERTY", "property": "lifecyclestage", "operation": {"operationType": "ENUMERATION", "operator": "IS_ANY_OF", "values": ["customer"]}}]}]}} },
  ],
  refusals: [
    { code: "list_name_taken", when: 409, message: "A list with this name already exists for this object type." },
  ],
  request: {
    method: "POST",
    path: "/crm/v3/lists",
    pathParams: [],
    query: {},
    body: {"name": "name", "objectTypeId": "object_type_id", "processingType": "processing_type", "filterBranch": "filter_branch", "customProperties": "custom_properties"},
    headers: {},
  },
  cost: { per: "request" },
})

